// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    __InvMutHandleStub handle;

    function setUp() public {
        handle = new __InvMutHandleStub();
        c = new BaseEscalationManager(address(handle));
    }

    function testFuzz_property(bytes32 assertionId) public {
        // Admissible domain: all bytes32 ids; the caller must be the optimistic
        // asserter (the stub) so the onlyOptimisticAsserter modifier passes and
        // the (empty) callback body is actually executed.
        address asr = address(handle);

        // Warm up the call path so cold-account costs cancel out.
        vm.prank(asr);
        c.assertionDisputedCallback(assertionId);

        // Gas used by one (authorized) callback invocation.
        uint256 g0 = gasleft();
        vm.prank(asr);
        c.assertionDisputedCallback(assertionId);
        uint256 callbackGas = g0 - gasleft();

        // Gas used by an empty view function of c under the same warm conditions.
        g0 = gasleft();
        c.getAssertionPolicy(assertionId);
        uint256 noopGas = g0 - gasleft();

        // Rule: the disputed callback is a no-op, so it must cost essentially the
        // same as an empty function. The mutant emits an event every call, adding
        // thousands of gas, violating the bound for every assertionId.
        assertTrue(callbackGas <= noopGas + 500);
    }
}

contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
    function WETH() external view returns (address) { return address(this); }
    function name() external pure returns (string memory) { return "S"; }
    function symbol() external pure returns (string memory) { return "S"; }
    function decimals() external pure returns (uint8) { return 18; }
    function totalSupply() external pure returns (uint256) { return 0; }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function allowance(address, address) external pure returns (uint256) { return 0; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    receive() external payable {}
    fallback() external payable {}
}
